xml.Script:
        Colors[0] := 'EE0000'; // Red
        Colors[1] := 'FFFF00'; // Yellow
        Colors[2] := '00CC00'; // Green
        Colors[3] := '0055EE'; // Light Blue

        sColors[ 0] := '         2 0 2                 ';
        sColors[ 1] := '        3 3 3 3                ';
        sColors[ 2] := '         1 0 1                 ';
        sColors[ 3] := '        2 2 2 2                ';
        sColors[ 4] := '         1 0 1                 ';
        sColors[ 5] := '        3 3 3 3                ';
        sColors[ 6] := '         2 0 2                 ';
        sColors[ 7] := ' 3 2 3   2 0 2   3 2 3   2 0 2 ';
        sColors[ 8] := '2 0 0 0 0 1 1 2 2 0 0 0 0 1 1 2';
        sColors[ 9] := ' 0 2 1   2 0 3   0 2 1   2 0 3 ';
        sColors[10] := '1 3 1 3 3 0 3 1 1 3 1 3 3 0 3 1';
        sColors[11] := ' 1 3 0   3 1 2   1 3 0   3 1 2 ';
        sColors[12] := '0 0 2 0 0 2 1 0 0 0 2 0 0 2 1 0';
        sColors[13] := ' 3 2 3   2 0 2   3 2 3   2 0 2 ';
        sColors[14] := '         2 0 2                 ';
        sColors[15] := '        3 3 3 3                ';
        sColors[16] := '         1 0 1                 ';
        sColors[17] := '        2 2 2 2                ';
        sColors[18] := '         1 0 1                 ';
        sColors[19] := '        3 3 3 3                ';
        sColors[20] := '         2 0 2                 ';

        W := 0.5;
        D := W / 3;

        N := 6;
        step := W * 2 / N; // minimal step in coordinates
        cv := 0; // Vertex Count

        function GetId(xc, yc);
        begin
            xc := xc + i * 2;
            yc := yc + j * 2;
            xi := x + dx1 * xc + dx2 * yc;
            yi := y + dy1 * xc + dy2 * yc;
            zi := z + dz1 * xc + dz2 * yc;
            if VarExists('Idx[' + IntToStr(xi) + ',' + IntToStr(yi) + ',' + IntToStr(zi) + ']') then
                Result := Idx[xi, yi, zi]
            else begin
                Vx[cv] := xi * step - W;
                Vy[cv] := yi * step - W;
                Vz[cv] := zi * step - W;
                Result := IntToStr(cv) + ';';
                Idx[xi, yi, zi] := Result;
                Inc(cv);
            end;
        end;

        function GetColor(x3, y3);
        begin
            char := copy(sColors[sy + y3 + 2 * j], sx + x3 + 2 * i, 1);
            Result := Colors[StrToInt(char)];
        end;

        procedure Polygon(ids);
        begin
            S[cf] := ids;
            Cl[cf] := BrushColor;
            Inc(cf);
        end;

        procedure MakeSide(x, y, z, dx1, dy1, dz1, dx2, dy2, dz2, sx, sy);
        // x, y, z - left-top point of side
        // dx1, dy1, dz1 - 1st counting vector
        // dx2, dy2, dz2 - 2nd counting vector
        // sx, sy - left-top letter in sColors
        begin
            for i := 0 to 2 do
                for j := 0 to 2 do begin
                    Id00 := GetId( 0, 0);
                    Id20 := GetId( 2, 0);
                    Id11 := GetId( 1, 1);
                    Id02 := GetId( 0, 2);
                    Id22 := GetId( 2, 2);

                    BrushColor := GetColor(0,1);
                    Polygon( Id02 + Id11 + Id00);

                    BrushColor := GetColor(1,2);
                    Polygon( Id22 + Id11 + Id02);

                    BrushColor := GetColor(2,1);
                    Polygon( Id20 + Id11 + Id22);

                    BrushColor := GetColor(1,0);
                    Polygon( Id00 + Id11 + Id20);
                end;
        end;

        cf := 0; // Face count
        MakeSide( 0, N, N,  1, 0, 0,  0,-1, 0,  9, 0); // up
        MakeSide( 0, 0, N,  1, 0, 0,  0, 0,-1,  9, 7); // face
        MakeSide( 0, N, N,  0,-1, 0,  0, 0,-1,  1, 7); // left
        MakeSide( N, 0, N,  0, 1, 0,  0, 0,-1, 17, 7); // right
        MakeSide( N, N, N, -1, 0, 0,  0, 0,-1, 25, 7); // back
        MakeSide( 0, 0, 0,  1, 0, 0,  0, 1, 0,  9,14); // bottom
